CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.reconciliation_rulesets(ruleset_id BIGSERIAL PRIMARY KEY,version TEXT NOT NULL UNIQUE,rules JSONB NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.reconciliation_models(model_id BIGSERIAL PRIMARY KEY,version TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,configuration JSONB NOT NULL,local_execution BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_runs(aggregate_run_id BIGSERIAL PRIMARY KEY,ruleset_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.reconciliation_rulesets(ruleset_id),model_id BIGINT REFERENCES oc_candidate_knowledge.reconciliation_models(model_id),configuration_hash CHAR(64) NOT NULL,policies JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('PENDING','PLANNING','PLANNED','AGGREGATING','RECONCILING','PAUSING','PAUSED','CANCELLING','CANCELLED','PARTIAL','COMPLETED','FAILED')),last_completed_item_id BIGINT,cancellation_requested_at TIMESTAMPTZ,metrics JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.candidate_clusters(cluster_id BIGSERIAL PRIMARY KEY,aggregate_type TEXT NOT NULL,cluster_key CHAR(64) NOT NULL,review_state TEXT NOT NULL DEFAULT 'REQUIRED',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(cluster_key,active));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_run_items(item_id BIGSERIAL PRIMARY KEY,aggregate_run_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),cluster_key CHAR(64) NOT NULL,plan_action TEXT NOT NULL,state TEXT NOT NULL,candidate_versions JSONB NOT NULL,failure JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(aggregate_run_id,cluster_key));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.candidate_cluster_members(cluster_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidate_clusters(cluster_id),candidate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidates(candidate_id),candidate_version INTEGER NOT NULL,membership_state TEXT NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(cluster_id,candidate_id,candidate_version));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_assertions(aggregate_id BIGSERIAL PRIMARY KEY,cluster_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidate_clusters(cluster_id),aggregate_type TEXT NOT NULL,normalized_subject TEXT NOT NULL,normalized_predicate TEXT NOT NULL,normalized_object TEXT NOT NULL,review_state TEXT NOT NULL DEFAULT 'REQUIRED',verification_state TEXT NOT NULL DEFAULT 'UNVERIFIED',status TEXT NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE CHECK(published=FALSE),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_versions(aggregate_version_id BIGSERIAL PRIMARY KEY,aggregate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_assertions(aggregate_id),aggregate_run_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),version INTEGER NOT NULL,identity_hash CHAR(64) NOT NULL UNIQUE,candidate_version_ids JSONB NOT NULL,summary JSONB NOT NULL,contexts JSONB NOT NULL,provenance_chain JSONB NOT NULL,copyright_safe_display_state TEXT NOT NULL,superseded_by_version_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(aggregate_id,version));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_evidence_links(aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),candidate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidates(candidate_id),anchor_id BIGINT NOT NULL REFERENCES oc_document_intelligence.source_anchors(anchor_id),source_revision_id BIGINT NOT NULL REFERENCES oc_import.document_revisions(revision_id),PRIMARY KEY(aggregate_version_id,candidate_id,anchor_id));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_relationships(relationship_id BIGSERIAL PRIMARY KEY,cluster_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidate_clusters(cluster_id),source_candidate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidates(candidate_id),target_candidate_id BIGINT REFERENCES oc_candidate_knowledge.candidates(candidate_id),target_aggregate_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_assertions(aggregate_id),relationship_type TEXT NOT NULL,rationale TEXT NOT NULL,ruleset_version TEXT NOT NULL,model_version TEXT,confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),review_state TEXT NOT NULL,source_anchor_ids JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_source_independence(assessment_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),candidate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidates(candidate_id),lineage JSONB NOT NULL,independence_state TEXT NOT NULL,uncertainty NUMERIC NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_temporal_intervals(interval_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),candidate_id BIGINT REFERENCES oc_candidate_knowledge.candidates(candidate_id),context JSONB NOT NULL,starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_geographic_contexts(context_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),candidate_id BIGINT REFERENCES oc_candidate_knowledge.candidates(candidate_id),context JSONB NOT NULL,scope TEXT NOT NULL,uncertainty JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_taxon_links(link_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),candidate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidates(candidate_id),source_name TEXT NOT NULL,canonical_match_candidates JSONB NOT NULL,confidence NUMERIC,review_state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_measurement_summaries(summary_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),original_measurements JSONB NOT NULL,normalized_measurements JSONB NOT NULL,conversion_rule_version TEXT NOT NULL,summary JSONB NOT NULL,pooled_estimate_allowed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_confidence_assessments(assessment_id BIGSERIAL PRIMARY KEY,aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),formula_version TEXT NOT NULL,components JSONB NOT NULL,uncertainty JSONB NOT NULL,score NUMERIC,score_is_truth_probability BOOLEAN NOT NULL DEFAULT FALSE CHECK(score_is_truth_probability=FALSE));
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_conflicts(conflict_id BIGSERIAL PRIMARY KEY,cluster_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.candidate_clusters(cluster_id),category TEXT NOT NULL,incompatible_dimensions JSONB NOT NULL,compatible_dimensions JSONB NOT NULL,possible_explanation TEXT,unresolved_questions JSONB NOT NULL,reviewer_status TEXT NOT NULL,resolution_history JSONB NOT NULL DEFAULT '[]',source_anchor_ids JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_review_items(review_id BIGSERIAL PRIMARY KEY,aggregate_run_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),cluster_id BIGINT REFERENCES oc_candidate_knowledge.candidate_clusters(cluster_id),aggregate_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_assertions(aggregate_id),category TEXT NOT NULL,severity TEXT NOT NULL,evidence JSONB NOT NULL,state TEXT NOT NULL DEFAULT 'OPEN',action TEXT,rationale TEXT,reviewer TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_warnings(warning_id BIGSERIAL PRIMARY KEY,aggregate_run_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),item_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_run_items(item_id),code TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_run_events(event_id BIGSERIAL PRIMARY KEY,aggregate_run_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),event_type TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_tombstones(tombstone_id BIGSERIAL PRIMARY KEY,aggregate_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_assertions(aggregate_id),aggregate_version_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_versions(aggregate_version_id),reason TEXT NOT NULL,effective_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),replacement_aggregate_id BIGINT REFERENCES oc_candidate_knowledge.aggregate_assertions(aggregate_id),actor TEXT NOT NULL,audit_metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS oc_candidate_knowledge.aggregate_quality_metrics(metric_id BIGSERIAL PRIMARY KEY,aggregate_run_id BIGINT NOT NULL REFERENCES oc_candidate_knowledge.aggregate_runs(aggregate_run_id),metric_name TEXT NOT NULL,metric_value NUMERIC,dimensions JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS aggregate_review_queue_idx ON oc_candidate_knowledge.aggregate_review_items(state,severity,created_at);
CREATE INDEX IF NOT EXISTS aggregate_identity_idx ON oc_candidate_knowledge.aggregate_assertions(aggregate_type,normalized_subject,normalized_predicate,active);
